      Bytesrw.Bytes.Slice.t =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    let len = Bytes.length buf in
    let f3_length = Wire_runtime.Unchecked.u16be buf (v + 4) in
    let s1 = f3_length - 8 in
    if s1 < 0 || s1 > len - (v + 8) then Bytesrw.Bytes.Slice.eod
    else
      let p2 = v + 8 + s1 in
      Bytesrw.Bytes.Slice.make_or_eod buf ~first:(v + 8) ~length:(p2 - (v + 8))

  let[@inline] set_src_port (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.Unchecked.set_u16be buf (v + 0)
      ((x : Wire_runtime.UInt16.t :> int) land 0xffff)

  let[@inline] set_dst_port (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.Unchecked.set_u16be buf (v + 2)
      ((x : Wire_runtime.UInt16.t :> int) land 0xffff)

  let[@inline] set_length (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.Unchecked.set_u16be buf (v + 4)
      ((x : Wire_runtime.UInt16.t :> int) land 0xffff)

  let[@inline] set_checksum (b : 'b Wire_runtime.Buf.t) (v : 'b view) x =
    let buf = (b : _ Wire_runtime.Buf.t :> bytes) in
    Wire_runtime.Unchecked.set_u16be buf (v + 6)
      ((x : Wire_runtime.UInt16.t :> int) land 0xffff)

  type t = {
    src_port : Wire_runtime.UInt16.t;
    dst_port : Wire_runtime.UInt16.t;
    length : Wire_runtime.UInt16.t;
    checksum : Wire_runtime.UInt16.t;
    payload : Bytesrw.Bytes.Slice.t;
  }

  let pp ppf (r : t) =
    let field name pp_v x =
      Format.pp_print_space ppf ();
      Format.pp_print_string ppf (name ^ " = ");
      pp_v ppf x;
      Format.pp_print_char ppf ';'
    in
    Format.pp_open_hvbox ppf 2;
    Format.pp_print_char ppf '{';
    field "src_port" Wire_runtime.UInt16.pp r.src_port;
    field "dst_port" Wire_runtime.UInt16.pp r.dst_port;
    field "length" Wire_runtime.UInt16.pp r.length;
    field "checksum" Wire_runtime.UInt16.pp r.checksum;
    field "payload"
      (fun ppf s ->
        Format.pp_print_string ppf
          (String.escaped (Bytesrw.Bytes.Slice.to_string s)))
      r.payload;
    Format.pp_print_string ppf " }";
    Format.pp_close_box ppf ()

  let of_view (b' : 'b Wire_runtime.Buf.t) (_ : 'b Wire_runtime.Buf.length)
      (v' : 'b view) : t =
    {
      src_port = src_port b' v';
      dst_port = dst_port b' v';
      length = length b' v';
      checksum = checksum b' v';
      payload = payload b' v';
    }

  let encode_at ~write (r : t) buf p =
    let f1_src_port = (r.src_port : Wire_runtime.UInt16.t :> int) in
    let f2_dst_port = (r.dst_port : Wire_runtime.UInt16.t :> int) in
    let f3_length = (r.length : Wire_runtime.UInt16.t :> int) in
    let f4_checksum = (r.checksum : Wire_runtime.UInt16.t :> int) in
    if write then begin
      Bytes.set_uint16_be buf (p + 0) (f1_src_port land 0xffff);
      Bytes.set_uint16_be buf (p + 2) (f2_dst_port land 0xffff);
      Bytes.set_uint16_be buf (p + 4) (f3_length land 0xffff);
      Bytes.set_uint16_be buf (p + 6) (f4_checksum land 0xffff)
    end;
    let q1 = p + 8 in
    let q3 = f3_length - 8 in
    refuse_if (q3 < 0) "a negative size";
    refuse_if
      (Bytesrw.Bytes.Slice.length r.payload <> q3)
      "a field of bytes does not have its size";
    if write then
      Bytes.blit
        (Bytesrw.Bytes.Slice.bytes r.payload)
        (Bytesrw.Bytes.Slice.first r.payload)
        buf q1 q3;
    let q2 = q1 + q3 in
    q2

  let size r = encode_at ~write:false r Bytes.empty 0

  let check_pass ~all buf length p0 path =
    if all && p0 + 6 <= length then begin
      let f3_length = Bytes.get_uint16_be buf (p0 + 4) in
      field_unless
        ((f3_length : int) >= 8)
        (p0 + 4) (path @ [ "length" ]) f3_length
    end;
    ()

  let[@inline never] error_at buf length p0 path =
    check_pass ~all:false buf length p0 path;
    eof_if (p0 > length - 8) p0 8 (max 0 (length - p0)) path;
    eof_if (p0 + 0 > length - 2) (p0 + 0) 2 (length - (p0 + 0)) path;
    eof_if (p0 + 2 > length - 2) (p0 + 2) 2 (length - (p0 + 2)) path;
    eof_if
      (p0 + 4 > length - 2)
      (p0 + 4) 2
      (length - (p0 + 4))
      (path @ [ "length" ]);
    let f3_length = Bytes.get_uint16_be buf (p0 + 4) in
    field_unless
      ((f3_length : int) >= 8)
      (p0 + 4) (path @ [ "length" ]) f3_length;
    eof_if (p0 + 6 > length - 2) (p0 + 6) 2 (length - (p0 + 6)) path;
    let q1 = p0 + 8 in
    let q3 = f3_length - 8 in
    eof_if (q3 < 0 || q3 > length - q1) q1 (max 0 q3) (length - q1) path;
    let q2 = q1 + q3 in
    q2
end

