    if
      ((f7_flags land 1 : int) = 0 && (f8_fragment_offset : int) = 0)
      && (f10_protocol : int) = 6
    then (
      let q6 = f5_total_length - (f2_ihl lsl 2) in
      eof_if
        (q6 < 0 || q6 > length - q2)
        q2 (max 0 q6) (length - q2) (path @ [ "tcp" ]);
      let q7 = min length (q2 + q6) in
      let q8 =
        let length = q7 in
        let q9 = Stack_tcp.error_at buf length q2 (path @ [ "tcp" ]) in
        q9 - q2
      in
      eof_if (q8 > q6) (q2 + min q8 q6) q6 q8 path;
      let q5 = q2 + q6 in
      q5)
    else q2

  let[@inline never] error_at'q17 buf length _p0 path q4 f2_ihl f5_total_length
      f7_flags f8_fragment_offset f10_protocol =
    if
      ((f7_flags land 1 : int) = 0 && (f8_fragment_offset : int) = 0)
