      eof_if
        (q13 < 0 || q13 > length - q4)
        q4 (max 0 q13) (length - q4) (path @ [ "udp" ]);
      let q14 = min length (q4 + q13) in
      let q15 =
        let length = q14 in
        let q16 = Stack_udp.error_at buf length q4 (path @ [ "udp" ]) in
